static Project rippleFixture(){
    auto p=emptyProject();p.songMode=true;p.loop=true;p.bpm=120;p.patterns[0].length=4;p.patterns[0].lanes[7]={{0,1,60,.8f}};
    p.clips={{7,0,0,4},{7,0,4,4},{7,0,8,4}};
    p.markers={{"a","Before",0,4,1},{"b","Cut",4,8,2},{"c","After",8,12,3},{"wide","Whole",0,12,4},{"point","Point",6,-1,5},{"edge","Edge",8,-1,6}};std::sort(p.markers.begin(),p.markers.end(),[](const SongMarker& a,const SongMarker& b){return a.beat==b.beat?a.id<b.id:a.beat<b.beat;});p.loopSection="b";p.recording.punch=true;p.recording.punchStart=4;p.recording.punchEnd=8;return p;
}
