    expect(!findSongMarker(out,"b")&&!findSongMarker(out,"point")&&findSongMarker(out,"edge")->beat==4&&findSongMarker(out,"wide")->endBeat==8&&stats.removedMarkers==2,"delete removes contained markers/sections but retains the end-edge cue and shrinks enclosing sections");
