    auto edge=emptyProject();edge.clips={{7,0,4091,1}};expect(ripplePlaylist(edge,4091,4,false,out).wasOk()&&out.clips[0].beat+out.clips[0].length==4096,"insertion ending exactly at the timeline limit is accepted");
