    auto mixed=source;Clip audio;audio.audioPath=sample.getFullPathName();audio.track=6;audio.beat=8;audio.length=2;audio.sourceOffset=.125;audio.gain=.6f;audio.fadeIn=.25;audio.fadeOut=.5;audio.fadeInCurve=FadeCurve::equalPower;audio.fadeOutCurve=FadeCurve::sCurve;Clip automation;automation.track=3;automation.beat=8;automation.length=4;automation.automationTarget=0;automation.automationTrack=7;automation.automationTrim=true;automation.points={{0,.6f,false,AutomationCurve::smooth,.2f},{4,.7f,true}};mixed.clips.push_back(audio);mixed.clips.push_back(automation);auto hash=SHA256(sample).toHexString();
    expect(ripplePlaylist(mixed,4,4,false,out).wasOk()&&out.clips[3].beat==12&&out.clips[4].beat==12,"audio and relative automation ripple together with patterns");auto movedAudio=out.clips[3];movedAudio.beat=audio.beat;auto movedCurve=out.clips[4];movedCurve.beat=automation.beat;auto unchangedAudio=mixed;unchangedAudio.clips={audio,automation};auto payload=out;payload.clips={movedAudio,movedCurve};expect(JSON::toString(projectToJson(unchangedAudio)["clips"])==JSON::toString(projectToJson(payload)["clips"])&&SHA256(sample).toHexString()==hash,"ripple preserves audio offset/fades/gain and complete Trim curves without touching media files");
    auto manual=mixed;manual.clips[1].beat=8;manual.clips[2].beat=12;manual.clips[3].beat=12;manual.clips[4].beat=12;manual.markers=out.markers;manual.recording=out.recording;expect(render(out,assets,root,410000,127)==render(manual,assets,root,410000,1024),"mixed ripple playback matches explicitly authored positions across callback sizes");
    mixed.clips[3].beat=3;sentinel=JSON::toString(projectToJson(out));stats.movedClips=99;expect(reject(mixed,4,4,false),"crossing audio rejects instead of changing source offsets or fades");mixed.clips[3].beat=8;mixed.clips[4].beat=3;expect(reject(mixed,4,4,true),"crossing automation rejects instead of changing underlying curve shapes");
    expect(applyControlEdits(source,JSON::parse(R"([{"op":"ripple_time","start":4,"length":4,"remove":false}])"),out).wasOk()&&out.clips[1].beat==8,"structured MCP ripple uses the same complete arrangement transform");sentinel=JSON::toString(projectToJson(out));for(auto json:{R"([{"op":"ripple_time","start":4,"length":4}])",R"([{"op":"ripple_time","start":4,"length":4,"remove":1}])",R"([{"op":"ripple_time","start":"4","length":4,"remove":false}])",R"([{"op":"ripple_time","start":4,"length":4,"remove":false,"lane":0}])",R"([{"op":"ripple_time","start":4,"length":4,"remove":false},{"op":"set_pattern","pattern":99,"name":"bad"}])"})expect(applyControlEdits(source,JSON::parse(json),out).failed()&&JSON::toString(projectToJson(out))==sentinel,"missing/wrong fields and later batch failures reject atomically");
